{
  "findings": [
    {
      "check_id": "CKV_AWS_53",
      "title": "Ensure S3 bucket has block public ACLS enabled",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The 'block_public_acls' argument is missing, which defaults to false. This allows public access via Access Control Lists (ACLs), potentially exposing the bucket contents."
    },
    {
      "check_id": "CKV_AWS_54",
      "title": "Ensure S3 bucket has block public policy enabled",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The 'block_public_policy' argument is missing, which defaults to false. This allows users with write permissions to add bucket policies that grant public access."
    },
    {
      "check_id": "CKV_AWS_55",
      "title": "Ensure S3 bucket has ignore public ACLs enabled",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The 'ignore_public_acls' argument is missing, which defaults to false. This means existing public ACLs on the bucket are not ignored and can still grant access."
    },
    {
      "check_id": "CKV_AWS_56",
      "title": "Ensure S3 bucket has 'restrict_public_buckets' enabled",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The 'restrict_public_buckets' argument is explicitly set to false. This should be true to restrict access to buckets and objects granted through new or existing public bucket/object ACLs."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket_public_access_block\" \"api_docs\" {\n  bucket                  = aws_s3_bucket.api_docs.id\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}",
  "fix_summary": "Enabled all four public access block settings ('block_public_acls', 'block_public_policy', 'ignore_public_acls', and 'restrict_public_buckets') by setting them to true to prevent unauthorized public access to the S3 bucket."
}
